"""Source-verified scoped IQ-TREE catalog metadata and actionable recovery."""
import json
from iqtree_workflow_validation import verify,sha
from catalog_source_integrity import verify_source

def iqtree_metadata(root,data):
    verify(root,data,emit=False)
    proof=json.loads((data/'iqtree-workflow-validation.json').read_bytes())
    roles=json.loads((data/'iqtree-role-coverage.json').read_bytes())
    assert roles['status']=='passed-nine-IQ-TREE-primary-source-role-reviews' and roles['applied'] is True
    assert roles['reviewed_roles']==9 and roles['total_reviews']==752 and roles['whole_paper_reproduced'] is False
    verify_source(root,data,'tools/literature/reviewed-uses.json',roles['reviews_sha256'])
    for name,field in [('tools/literature/curate_iqtree_uses.py','curator_sha256'),('tools/literature/iqtree-use-reviews.json','draft_sha256')]:
        assert sha((root/name).read_bytes())==roles[field]
    return dict(implementation_status='upstream-adapter-validated',
        implementation_source='src/main/java/org/jlinalg/cli/IqtreeToolsCli.java',
        coverage_note='The pre-expansion inventory lacked IQ-TREE. Current source adds a validated scoped single-alignment command; nine paper roles retain explicit edition, alphabet, model and downstream-analysis boundaries.',
        implementation_scope='Runs exact original Linux x86_64 editions 1.6.12, 2.1.2, 2.1.4-beta, 2.2.0.3, 2.3.1, 2.3.5, 2.3.6 and 2.4.0 through iqtree-tools. Accepts complete DNA, protein or standard-code codon alignments in FASTA or explicit PHYLIP. Supports fixed built-in models, ModelFinder/TEST, inference or fixed-tree evaluation, standard/ultrafast bootstrap and SH-aLRT. Java audits identities, every model candidate and site likelihood, complete bootstrap families and reported support edges. Native JC69 adds an independent likelihood check; other fitted models receive source consistency audits. Every original row/site and raw source value is retained. KEEP requests all rows; SOURCE_REMOVE_RESTORE records the actual fitted population and restores full names. Setup requires Linux Python 3.11+, prlimit, setsid and explicit permitted install/download flags. Analysis requires Linux Java (WSL on Windows). SKIP3 means skip an unavailable runtime/capability; FAIL2 means no admitted result after input, integrity, execution, capacity or finalization failure. Require COMPLETED.json and matching hashes. Review source-clamped AICc, ignored frequency requests and signed roundoff. Read IQTREE_DEVELOPMENT.md. Partitions, dating, batch gene trees, custom/mixture models, other codes/formats, unresolved paper settings and biological accuracy remain open.',
        validation_note='All 530 focused tests pass on Linux and against the executable JAR. Windows Java 21 and 25 each pass 495 with 35 Linux/runtime aborts. The full Java gate has 6203 passes and 254 environment skips. All 21 public protocols match expectations: 17 completed fits, two skips and two failures across eight exact editions. They retain 6744 site cells, 6264 independent JC69 comparisons, 1100 bootstrap trees, 36 support comparisons and 71 ModelFinder candidates. Each 36-row duplicate control explicitly fits 24 rows and restores 12 pruned names. A Linux bundle verifies on Windows; changed bytes and extra empty directories fail. Eight evidence tests cover changed science, truncated output, scope/count relabelling and unsafe archives. Nine paper roles are reviewed. Literal 1.6.619, GTR+F3x4+R6 and -AUTO remain unresolved/refused. No paper-tree reconstruction or biological-accuracy certificate is claimed.',
        project_adapter_available=True,canonical_adapter_available=False,development_adapter_cli='iqtree-tools',
        development_candidate=proof['packaged_candidate'],development_candidate_sha256=proof['packaged_candidate_sha256'],
        workflow_validation='iqtree-workflow-validation.json',source_role_coverage='iqtree-role-coverage.json',source_roles_reviewed=9,
        whole_paper_reproduced=False,biological_accuracy_certified=False,runtime_profiles=['linux-x86_64-iqtree-'+v for v in proof['exact_editions']],
        runtime_setup_export_available=True,download_install_available=True,runtime_installer='tools/literature/install_iqtree.py',
        native_helpers=['src/main/java/org/jlinalg/phylogeny/PhylogeneticAlignment.java','src/main/java/org/jlinalg/phylogeny/NewickTree.java','src/main/java/org/jlinalg/phylogeny/NewickReader.java','src/main/java/org/jlinalg/phylogeny/JukesCantorLikelihood.java','src/main/java/org/jlinalg/phylogeny/BootstrapSupport.java'])

IQTREE_WARNING='''**IQ-TREE SINGLE ALIGNMENT: EXACT RUNTIME, SOURCE VALUES AND REQUIRED RECOVERY.** Use current-source iqtree-tools; previously released 0.3.7 JARs do not gain this command automatically. Read [IQTREE_DEVELOPMENT.md](../IQTREE_DEVELOPMENT.md), [the workflow proof](iqtree-workflow-validation.json) and [the nine primary-paper roles](iqtree-role-coverage.json). Build the checkout or use its exact tested candidate. Export setup with iqtree-tools --export-runtime-setup NEW_DIRECTORY; use Linux x86_64 Python3.11+, permitted prlimit/setsid and the README's explicit install/download flags. Analysis requires Linux Java (WSL on Windows), an exact admitted private home and a NEW output directory on a filesystem preserving POSIX modes.

**Unavailable/forbidden runtime or unsupported capability: SKIP3; skip dependent analysis. Invalid data,integrity,execution,capacity or finalization: FAIL2; no result is admitted.** Required action: read WARNINGS.md,session.json,output-audit.json,analyzed-population.json and process logs; preserve partial files, correct the named cause and rerun to NEW paths. Require COMPLETED.json and iqtree-tools --verify DIRECTORY. Byte hashes are not signatures or biological-accuracy certificates.

Every original row/site and source value is retained. SOURCE_REMOVE_RESTORE explicitly allows duplicate pruning: inspect the actual fitted population rather than claiming every original row contributed to fitting. KEEP requests all rows. Source-clamped small-sample AICc can be finite while classical AICc is undefined; ignored model-frequency requests and signed roundoff remain warnings. Native JC69 supplies an independent check; other fitted models receive source consistency audits. Bootstrap algorithm and SH-aLRT are distinct choices.

**Paper-exact settings needing clarification remain unavailable:** P109 literal1.6.619 and unspecified input alphabet; P066 original2.3.1 refuses GTR+F3x4+R6; P171 original2.3.5 refuses-AUTO. P235 does not specify the bootstrap algorithm or dating edition. Do not substitute editions/models or infer effective author commands. Partitions,dating,batch gene trees,custom/mixture models,other genetic codes/formats and paper reconstruction remain unfinished. Cell Ranger remains excluded.

'''

